}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  background:
    radial-gradient(ellipse 70% 52% at 80% 0%, var(--green-wash), transparent 62%),
    var(--paper);
  color: var(--ink);
  font-family: var(--mono-body);
  line-height: 1.65;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--accent-dim);
  font-weight: 700;
}

.keating-artifact {
  min-height: 100vh;
  padding: clamp(1rem, 3vw, 2.5rem);
}

.keating-artifact-shell {
  width: min(92vw, 1280px);
  margin: 0 auto;
  display: grid;
  gap: 1rem;
}

.keating-artifact-header {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: end;
  border: 1.5px solid var(--ink);
  background: var(--card);
  box-shadow: 4px 4px 0 var(--ink);
  padding: clamp(1rem, 2vw, 1.5rem);
}

.keating-artifact-title {
  margin: 0.25rem 0 0;
  color: var(--accent-dim);
  font-family: var(--mono-display);
  font-size: clamp(1.8rem, 4vw, 3.5rem);
  line-height: 1.05;
  letter-spacing: -0.025em;
}

.keating-artifact-meta {
  color: var(--ink-soft);
  font-size: 0.78rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.keating-artifact-links {
  display: grid;
  gap: 0.35rem;
  justify-items: end;
  font-size: 0.86rem;
}

.keating-crt-panel {
  position: relative;
  overflow: hidden;
  border: 1.5px solid var(--ink);
  background: var(--terminal);
  color: var(--phosphor);
  box-shadow: 6px 6px 0 var(--ink);
}

.keating-crt-panel::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(0, 0, 0, 0.16) 0 1px, transparent 1px 3px);
  mix-blend-mode: multiply;
}

@media (max-width: 720px) {
  .keating-artifact-header {
    align-items: start;
    flex-direction: column;
  }

  .keating-artifact-links {
    justify-items: start;
  }
}
